    [4130]={name="Smotts' Compass",sourceType="quest_reward",instructions="Reward from the quest “Facing Negolash”. In Stranglethorn Vale.",zone="Stranglethorn Vale",questName="Facing Negolash",lore="Negolash is a hungry giant. When the giants destroyed our ship, Negolash went straight for my kitchen. He wasn't hungry for crew like the other giants."},
    [4134]={name="Nimboya's Mystical Staff",sourceType="quest_reward",instructions="Reward from the quest “Saving Yenniku” — pick it over the other choices. In Stranglethorn Vale.",zone="Stranglethorn Vale",questName="Saving Yenniku",lore="I have reshaped the Mind's Eye into a Soul Gem. Its purpose is twofold: you must use it to stun Yenniku, and once stunned place it upon his head to entrap his soul."},
