    [4545]={name="Radiant Silver Bracers",sourceType="quest_reward",instructions="Reward from the quest “Foul Magics” — pick it over the other choices. In Arathi Highlands.",zone="Arathi Highlands",questName="Foul Magics",lore="There is no doubt in my mind that a powerful warlock resides within the walls of Stromgarde. From time to time, using an arcane magical relic, this warlock has summoned forth terrible demons in large numbers."},
