    [4915]={name="Soft Wool Boots",sourceType="quest_reward",instructions="Reward from the quest “Cutting Teeth” — pick it over the other choices. In Valley of Trials.",zone="Valley of Trials",questName="Cutting Teeth",lore="The first order of business will be to put a little strength in your backbone. I could send you out to the Barrens to hunt kodo, but well, in all honesty, you're more useful to us alive than dead."},
    [4916]={name="Soft Wool Vest",sourceType="quest_reward",instructions="Reward from the quest “Sarkoth” — pick it over the other choices. In Valley of Trials.",zone="Valley of Trials",questName="Sarkoth",lore="Seeing the deed you have done for me steels my heart. I cannot fall so easily! I must endure! But it remains that I cannot make the trek back to the Den unassisted."},
    [4919]={name="Soft Wool Belt",sourceType="quest_reward",instructions="Reward from the quest “Sting of the Scorpid” — pick it over the other choices. In Valley of Trials.",zone="Valley of Trials",questName="Sting of the Scorpid",lore="Powerful warrior and awkward novice alike have fallen to the venomous sting of the scorpid. You will find large numbers of scorpids northwest of here."},
    [4936]={name="Dirt-trodden Boots",sourceType="quest_reward",instructions="Reward from the quest “From The Wreckage....” — pick it over the other choices. In Durotar.",zone="Durotar",questName="From The Wreckage....",lore="One of my most observant scouts brings back word that the wreckage of Proudmoore's fleet still remains off the coast of Durotar, just east of Tiragarde Keep."},
    [4979]={name="Enchanted Stonecloth Bracers",sourceType="quest_reward",instructions="Reward from the quest “Stone Is Better than Cloth”. In Badlands.",zone="Badlands",questName="Stone Is Better than Cloth",lore="Maybe it'll even help protect you from the coming atrocity that is Lotwil's newest invention. I've been working with all the extra stones you collected for him, and I can make some nice bracers that you might want to use."},
