    [6266]={name="Disciple's Vest",sourceType="world_drop",instructions="World drop — drops from 380 creature types around level 8-14. Also found on the auction house."},
    [6282]={name="Sacred Burial Trousers",sourceType="quest_reward",instructions="Reward from the quest “Battle of Hillsbrad” — pick it over the other choices. In Hillsbrad Foothills.",zone="Hillsbrad Foothills",questName="Battle of Hillsbrad",lore="Because you fought with such valor and perseverance in the Battle of Hillsbrad, I have written this commendation, extolling your heroics in combat for the high command to recognize."},
    [6324]={name="Robes of Arugal",sourceType="boss_drop",instructions="Drops from Archmage Arugal in Shadowfang Keep.",zone="Shadowfang Keep",npc="Archmage Arugal",lore="Archmage Arugal called the worgen to Silverpine to defend against the Scourge, lost control of them immediately, and went mad in Shadowfang Keep among the things he had summoned."},
    [6341]={name="Eerie Stable Lantern",sourceType="boss_drop",instructions="Drops from Fel Steed.",npc="Fel Steed"},
    [6378]={name="Seer's Cape",sourceType="world_drop",instructions="World drop — drops from 376 creature types around level 11-18. Also found on the auction house."},
    [6392]={name="Belt of Arugal",sourceType="boss_drop",instructions="Drops from Archmage Arugal in Shadowfang Keep.",zone="Shadowfang Keep",npc="Archmage Arugal",lore="Arugal's own belt. He summoned the worgen to save Silverpine, then lost his mind in Shadowfang Keep surrounded by what he had called."},
    [6395]={name="Silver-thread Amice",sourceType="world_drop",instructions="World drop — drops from 301 creature types around level 24-30. Also found on the auction house."},
