    [9513]={name="Ley Staff",sourceType="quest_reward",instructions="Reward from the quest “Mirror Lake” — pick it over the other choices.",questName="Mirror Lake",lore="This world has been victim to massive mystic struggles, which tore magic currents from once stable channels. We struggle to determine the effects these changes have caused, and some of us fear the worst!"},
    [9514]={name="Arcane Staff",sourceType="quest_reward",instructions="Reward from the quest “Mage-tastic Gizmonitor” — pick it over the other choices.",questName="Mage-tastic Gizmonitor",lore="We mages do more than just waggle our fingers and make pretty sparks! We control magic, the base fabric of our world! And that takes great care, and resolve."},
    [9517]={name="Celestial Stave",sourceType="quest_reward",instructions="Reward from the quest “Celestial Power” — pick it over the other choices.",questName="Celestial Power"},
    [9603]={name="Gritroot Staff",sourceType="quest_reward",instructions="Reward from the quest “The Relics of Wakening” — pick it over the other choices. In Teldrassil.",zone="Teldrassil",questName="The Relics of Wakening",lore="Gnarlpine invaders were seen ravaging the Ban'ethil Barrow Den to the west. The slumbering druids will be trapped in the Emerald Dream for eternity, unaware of their fate, unless we help."},
    [9658]={name="Boots of the Maharishi",sourceType="quest_reward",instructions="Reward from the quest “Gordunni Cobalt” — pick it over the other choices. In Feralas.",zone="Feralas",questName="Gordunni Cobalt",lore="I just arrived here in Feralas, and I've heard that the Gordunni Ogres that inhabit the wilds here have some interesting minerals. Who knows what they are up to, but they sure are protective of that stuff!"},
