    [10637]={name="Brewer's Gloves",sourceType="quest_reward",instructions="Reward from the quest “Sample for Helbrim” — pick it over the other choices. In Undercity.",zone="Undercity",questName="Sample for Helbrim",lore="A colleague in Kalimdor, Apothecary Helbrim, is researching the effects of Lordaeron toxins on the beasts of Kalimdor. He would be very interested in a sample of the wolf hearts Renferrel sent me."},
    [10654]={name="Jutebraid Gloves",sourceType="quest_reward",instructions="Reward from the quest “Horde Presence” — pick it over the other choices. In The Barrens.",zone="The Barrens",questName="Horde Presence",lore="This scroll is from that scheming dryad Rynthariel, Keymaster of the Talon Den on Stonetalon Peak. She'll not be making any more contact with the messenger you looted this from, heh, but we must stand our ground here."},
    [10657]={name="Talbar Mantle",sourceType="quest_reward",instructions="Reward from the quest “In Nightmares” — pick it over the other choices. In The Barrens.",zone="The Barrens",questName="In Nightmares",lore="This shard holds great secrets; it is the pure essence of the Emerald Dream. However, what I see in this shard is not a dream; one would call this sort of a vision a nightmare."},
    [10659]={name="Shard of the Splithooves",sourceType="quest_reward",instructions="Reward from the quest “Heroes of Old”. In Blasted Lands.",zone="Blasted Lands",questName="Heroes of Old",lore="Please, take from this a relic of old. We no longer have a use for the item. May it serve you well in your fight against the legion."},
