    [10919]={name="Apothecary Gloves",sourceType="quest_reward",instructions="Reward from the quest “Serpentbloom”. In Wailing Caverns.",zone="Wailing Caverns",questName="Serpentbloom",lore="A like you must get pretty hungry out here in The Barrens. Me, I'm starving all day long. Tell you what, I'll fix you up a nice stew. Just need a few dig rats."},
    [11187]={name="Stemleaf Bracers",sourceType="quest_reward",instructions="Reward from the quest “The Balance of Nature” — pick it over the other choices. In Shadowglen.",zone="Shadowglen",questName="The Balance of Nature",lore="Greetings. I am Conservator Ilthalaine. My purpose in Shadowglen is to ensure that the balance of nature is maintained."},
    [11189]={name="Woodland Robes",sourceType="quest_reward",instructions="Reward from the quest “Webwood Egg” — pick it over the other choices. In Shadowglen.",zone="Shadowglen",questName="Webwood Egg",lore="Now that I have the spiders' venom, I'd like some live specimens to study. Unfortunately, capturing a living, giant spider is more than I can ask of you, young."},
    [11190]={name="Viny Gloves",sourceType="quest_reward",instructions="Reward from the quest “The Woodland Protector” — pick it over the other choices. In Shadowglen.",zone="Shadowglen",questName="The Woodland Protector",lore="Something evil is brewing in the forests of Teldrassil. Look long the hills to where the peaceful furbolgs used to dwell. They have deserted their homes and are amassing under the name of the Gnarlpine tribe."},
