    [12053]={name="Volcanic Rock Ring",sourceType="world_drop",instructions="World drop — drops from 371 creature types around level 16-22. Also found on the auction house."},
    [12113]={name="Sunborne Cape",sourceType="quest_reward",instructions="Reward from the quest “Disharmony of Fire” — pick it over the other choices. In Blackrock Depths.",zone="Blackrock Depths",questName="Disharmony of Fire",lore="I can taste the foulness in the air that surrounds you. There is another, hidden in the depths of Blackrock, who does control this foulness."},
    [12295]={name="Leggings of the People's Militia",sourceType="quest_reward",instructions="Reward from the quest “Red Leather Bandanas” — pick it over the other choices. In Westfall.",zone="Westfall",questName="Red Leather Bandanas",lore="The Defias Front is constantly shifting. I've been following their movements for quite some time now. On a side note, I've ascertained that many members of the gang can be tracked by the Red Leather Bandanas they wear."},
    [12296]={name="Spark of the People's Militia",sourceType="quest_reward",instructions="Reward from the quest “The People's Militia” — pick it over the other choices. In Westfall.",zone="Westfall",questName="The People's Militia",lore="We believe they are hiding out in the Dagger Hills, plotting their next move. Slay the wretches in the name of The People's Militia."},
    [12462]={name="Embrace of the Wind Serpent",sourceType="boss_drop",instructions="Drops from Avatar of Hakkar.",npc="Avatar of Hakkar"},
    [12466]={name="Dawnspire Cord",sourceType="boss_drop",instructions="Drops from Morphaz in Sunken Temple.",zone="Sunken Temple",npc="Morphaz"},
    [12543]={name="Songstone of Ironforge",sourceType="quest_reward",instructions="Reward from the quest “The Princess's Surprise” — pick it over the other choices. In Blackrock Depths.",zone="Blackrock Depths",questName="The Princess's Surprise",lore="You ruined my life and the life of my unborn child! Return to Ironforge and tell my father that the heir to the Kingdom of Ironforge will be a Dark Iron dwarf."},
    [12545]={name="Eye of Orgrimmar",sourceType="quest_reward",instructions="Reward from the quest “The Princess Saved?” — pick it over the other choices. In Blackrock Depths.",zone="Blackrock Depths",questName="The Princess Saved?",lore="You have slain my husband! My child will be born into this world without a father. I assure you, this child will be the next ruler of the kingdom of Ironforge."},
