    [18814]={name="Choker of the Fire Lord",sourceType="boss_drop",instructions="Drops from Ragnaros.",npc="Ragnaros",lore="The Firelord, one of the four Elemental Lords, bound to the Elemental Plane until the Dark Iron dwarves summoned him under Blackrock Mountain. The summoning cracked the mountain open and made the Molten Core."},
    [18957]={name="Brushwood Blade",sourceType="quest_reward",instructions="Reward from the quest “Druid of the Claw” — pick it over the other choices. In Teldrassil.",zone="Teldrassil",questName="Druid of the Claw",lore="After examining this charm, I see now what must be done. Please take it, and do as I ask. You are to explore the deepest areas of the Ban'ethil Barrow Den."},
    [19086]={name="Stormpike Sage's Cloak",sourceType="vendor",instructions="Bought from Gaelden Hammersmith in Alterac Valley — costs tokens or reputation.",zone="Alterac Valley",npc="Gaelden Hammersmith"},
    [19108]={name="Wand of Biting Cold",sourceType="quest_reward",instructions="Reward from the quest “The Legend of Korrak” — pick it over the other choices. In Alterac Valley.",zone="Alterac Valley",questName="The Legend of Korrak",lore="The invading Stormpike are not the only threat in the region, soldier. The war in the Valley is waged on two fronts. The cannibal Winterax trolls also vie for power."},
    [19115]={name="Flask of Forest Mojo",sourceType="quest_reward",instructions="Reward from the quest “Return to Primal Torntusk” — pick it over the other choices. In The Hinterlands.",zone="The Hinterlands",questName="Return to Primal Torntusk",lore="Return to my mate, Primal Torntusk at Revantusk Village. Tell her that I am coming home! She is sure to reward you."},
    [19121]={name="Deep Woodlands Cloak",sourceType="quest_reward",instructions="Reward from the quest “Wanted: Vile Priestess Hexx and Her Minions” — pick it over the other choices. In The Hinterlands.",zone="The Hinterlands",questName="Wanted: Vile Priestess Hexx and Her Minions",lore="By order of Primal Torntusk, Vile Priestess Hexx and her minions are to be brought to justice! A grand reward is offered for any that slay the Vile Priestess Hexx and all of her Aman'zasi elite guard."},
    [19136]={name="Mana Igniting Cord",sourceType="boss_drop",instructions="Drops from Garr in Molten Core.",zone="Molten Core",npc="Garr",lore="A lieutenant of Ragnaros who fights surrounded by his Firesworn, and grows stronger each time one of them falls."},
    [19310]={name="Tome of the Ice Lord",sourceType="vendor",instructions="Bought from Gaelden Hammersmith in Alterac Valley — costs tokens or reputation.",zone="Alterac Valley",npc="Gaelden Hammersmith"},
