    [22496]={name="Frostfire Robe",sourceType="quest_reward",instructions="Reward from the quest “Frostfire Robe”. In Naxxramas.",zone="Naxxramas",questName="Frostfire Robe",lore="While the majority of the books were filled with - to put it bluntly - tripe, there were some gems. One of those tomes documented the creation of a set of armor fit for an archmage: Frostfire."},
    [22497]={name="Frostfire Leggings",sourceType="quest_reward",instructions="Reward from the quest “Frostfire Leggings”. In Naxxramas.",zone="Naxxramas",questName="Frostfire Leggings",lore="While the majority of the books were filled with - to put it bluntly - tripe, there were some gems. One of those tomes documented the creation of a set of armor fit for an archmage: Frostfire."},
